<?php
declare(strict_types=1);
function journey_node_order():array{return['node-1','node-2','node-3','node-4','node-5','node-6','node-7','node-final'];}
function journey_nodes():array{return['node-1'=>['id'=>'node-1','gameView'=>'MINIGAME_MEMORY','title'=>'A9: سنجش جامع حافظه','xpReward'=>300,'coinReward'=>50],'node-2'=>['id'=>'node-2','gameView'=>'MINIGAME_MATH','title'=>'A10: هوش ریاضی','xpReward'=>120,'coinReward'=>20],'node-3'=>['id'=>'node-3','gameView'=>'MINIGAME_SPEED','title'=>'A11: سرعت ادراکی','xpReward'=>150,'coinReward'=>25],'node-4'=>['id'=>'node-4','gameView'=>'MINIGAME_VISUALIZATION','title'=>'A12: تجسم فضایی','xpReward'=>180,'coinReward'=>30],'node-5'=>['id'=>'node-5','gameView'=>'MINIGAME_ORIENTATION','title'=>'A13: جهت‌یابی','xpReward'=>200,'coinReward'=>35],'node-6'=>['id'=>'node-6','gameView'=>'MINIGAME_STROOP','title'=>'A14: قدرت تمرکز','xpReward'=>220,'coinReward'=>40],'node-7'=>['id'=>'node-7','gameView'=>'MINIGAME_MULTITASK','title'=>'A15: مدیریت همزمان','xpReward'=>300,'coinReward'=>60],'node-final'=>['id'=>'node-final','gameView'=>'MINIGAME_FACTFINDING','title'=>'A18: حقیقت‌یابی (Boss)','xpReward'=>1000,'coinReward'=>200]];}
function get_journey_node(string $id):?array{$n=journey_nodes();return$n[$id]??null;}
function next_journey_node_id(string $id):?string{$o=journey_node_order();$i=array_search($id,$o,true);return($i===false||$i>=count($o)-1)?null:$o[$i+1];}
